from openai import OpenAI


def profile_moderation(profile_text: str) -> dict:
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
    moderation = client.moderations.create(model="omni-moderation-latest", input=profile_text)
    item = moderation.results[0]
    return {"flagged": item.flagged, "categories": item.categories.model_dump(), "category_scores": item.category_scores.model_dump()}
","onboarding_summary.py":"import os
from anthropic import Anthropic


def onboarding_summary(onboarding_state: str) -> dict:
    client = Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))
    message = client.messages.create(
        model="claude-3-5-sonnet-20240620",
        max_tokens=300,
        messages=[{"role": "user", "content": f"Summarize this onboarding state for support:\n{onboarding_state}"}],
    )
    text = "".join(part.text for part in message.content if hasattr(part, "text"))
    return {"summary": text}
","profile_note_store.py":"import os
from google.cloud import firestore


_COLLECTION = "onboarding_notes"


def profile_note_store(user_id: str, note: str, metadata: dict | None = None) -> dict:
    client = firestore.Client()
    doc = client.collection(_COLLECTION).document(user_id).collection("notes").document()
    payload = {"note": note, "metadata": metadata or {}, "provider": "google.firestore.v1.Firestore"}
    doc.set(payload)
    return {"document_id": doc.id, "user_id": user_id, "stored": True}
